import pulp

# Data
products = ['I', 'II', 'III']
quarters = [1, 2, 3, 4]

d = {
    ('I', 1): 1500, ('I', 2): 1000, ('I', 3): 2000, ('I', 4): 1200,
    ('II', 1): 1500, ('II', 2): 1500, ('II', 3): 1200, ('II', 4): 1500,
    ('III', 1): 1000, ('III', 2): 2000, ('III', 3): 1500, ('III', 4): 2500
}

h = {'I': 2, 'II': 4, 'III': 3}
H = {t: 15000 for t in quarters}

cL = {'I': 20, 'II': 20, 'III': 10}
cH = 5

I0 = {p: 0 for p in products}
IF = {p: 150 for p in products}

# Model
prob = pulp.LpProblem("Production_Planning", pulp.LpMinimize)

# Decision variables
x = pulp.LpVariable.dicts("x", [(p, t) for p in products for t in quarters], lowBound=0)
s = pulp.LpVariable.dicts("s", [(p, t) for p in products for t in quarters], lowBound=0)
b = pulp.LpVariable.dicts("b", [(p, t) for p in products for t in quarters], lowBound=0)
y = pulp.LpVariable.dicts("y", [(p, t) for p in products for t in quarters], lowBound=0)

# Objective
prob += pulp.lpSum(cL[p] * b[p, t] for p in products for t in quarters) + cH * pulp.lpSum(s[p, t] for p in products for t in [1, 2, 3])

# Constraints
# C1: Production capacity
for t in quarters:
    prob += pulp.lpSum(h[p] * x[p, t] for p in products) <= H[t]

# C2: Product I cannot be produced in Q2
prob += x['I', 2] == 0

# C3: Inventory/backorder balance
for p in products:
    for t in quarters:
        if t == 1:
            prob += s[p, t] - b[p, t] == I0[p] - 0 + x[p, t] - d[p, t]
        else:
            prob += s[p, t] - b[p, t] == s[p, t-1] - b[p, t-1] + x[p, t] - d[p, t]

# C4: Demand-fulfilment flow
for p in products:
    for t in quarters:
        if t == 1:
            prob += d[p, t] + 0 == y[p, t] + b[p, t]
        else:
            prob += d[p, t] + b[p, t-1] == y[p, t] + b[p, t]

# C5: Delivery availability
for p in products:
    for t in quarters:
        if t == 1:
            prob += y[p, t] <= I0[p] + x[p, t] + 0
        else:
            prob += y[p, t] <= s[p, t-1] + x[p, t] + b[p, t-1]

# C6: Required ending inventory
for p in products:
    prob += s[p, 4] == IF[p]

# C7: No backorders at end of horizon
for p in products:
    prob += b[p, 4] == 0

# Solve
prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))

print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
